DELIMITER $$
--
-- Procedimientos
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_gestionar_periodos_automaticos` ()   BEGIN
    DECLARE v_abiertos INT;
    DECLARE v_ultimo_fondo DECIMAL(15,2) DEFAULT 0;
    DECLARE v_id_anio_activo INT DEFAULT NULL;
    DECLARE v_cajas_abiertas INT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT 'Error crítico al ejecutar los cierres automáticos.' AS mensaje;
    END;

    START TRANSACTION;

    UPDATE anio_fiscal 
    SET estado = 'CERRADA', activo = 0 
    WHERE estado = 'ABIERTO' AND fecha_cierre < CURDATE() AND activo = 1;

    SELECT COUNT(*) INTO v_abiertos 
    FROM anio_fiscal 
    WHERE estado = 'ABIERTO' AND activo = 1;

    IF v_abiertos = 0 THEN
        VALUES (
            'ABIERTO', 
            CURDATE(), 
            DATE_ADD(CURDATE(), INTERVAL 1 YEAR), 
            CONCAT('Año fiscal automático ', YEAR(CURDATE())), 
            1
        );
    END IF;

    UPDATE caja_chica
    SET estado = 'CERRADA'
    WHERE estado = 'ABIERTO'
      AND (
          YEAR(fecha_creacion) < YEAR(CURDATE()) 
          OR 
          (YEAR(fecha_creacion) = YEAR(CURDATE()) AND MONTH(fecha_creacion) < MONTH(CURDATE()))
      );

    SELECT COUNT(*) INTO v_cajas_abiertas 
    FROM caja_chica 
    WHERE estado = 'ABIERTO' AND activo = 1;

    IF v_cajas_abiertas = 0 THEN
        
        SELECT id_anio_fiscal INTO v_id_anio_activo 
        FROM anio_fiscal 
        WHERE estado = 'ABIERTO' AND activo = 1 
        LIMIT 1;

        IF v_id_anio_activo IS NOT NULL THEN
            SELECT fondo_fijo INTO v_ultimo_fondo 
            FROM caja_chica 
            ORDER BY id_caja_chica DESC 
            LIMIT 1;

            VALUES (
                v_ultimo_fondo, 
                'ABIERTO', 
                CONCAT('Caja chica automática - Mes ', MONTH(CURDATE()), '/', YEAR(CURDATE())), 
                CURDATE(), 
                v_id_anio_activo, 
                1
            );
        END IF;
    END IF;

    COMMIT;
    SELECT 'Periodos (Año Fiscal y Caja Chica) verificados y gestionados correctamente.' AS mensaje;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrar_reposicion_caja` (IN `p_id_caja` INT, IN `p_concepto_id` INT, IN `p_proveedor_id` INT, IN `p_presupuesto_id` INT, IN `p_tasa_dolar` DECIMAL(15,2))   BEGIN
    DECLARE v_total_pendiente DECIMAL(15,2) DEFAULT 0;
    DECLARE v_gasto_id        INT;
    DECLARE v_estado_caja     VARCHAR(20);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    SELECT estado INTO v_estado_caja 
      FROM caja_chica 
     WHERE id_caja_chica = p_id_caja AND activo = 1 
     FOR UPDATE;

    IF v_estado_caja IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La caja chica no existe o fue eliminada.';
    END IF;
    IF UPPER(v_estado_caja) <> 'ABIERTO' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No se puede reponer una caja chica cerrada.';
    END IF;

    SELECT COALESCE(SUM(monto), 0) INTO v_total_pendiente
      FROM movimientos_caja
     WHERE caja_chica_id = p_id_caja AND estado = 'PENDIENTE' AND activo = 1 
     FOR UPDATE;

    IF v_total_pendiente <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No hay movimientos pendientes por reponer en esta caja.';
    END IF;

    -- Sin clasificacion: la columna ya no existe
    VALUES (p_tasa_dolar, p_concepto_id, p_proveedor_id, p_presupuesto_id,
            CONCAT('Reposición de Caja Chica - ', DATE_FORMAT(CURDATE(), '%d/%m/%Y')), 1);
    SET v_gasto_id = LAST_INSERT_ID();

    SELECT mc.fecha, mc.monto, 'EFECTIVO', v_gasto_id
      FROM movimientos_caja mc
     WHERE mc.caja_chica_id = p_id_caja AND mc.estado = 'PENDIENTE' AND mc.activo = 1;

    SELECT v_gasto_id, id_movimiento_caja 
      FROM movimientos_caja
     WHERE caja_chica_id = p_id_caja AND estado = 'PENDIENTE' AND activo = 1;

    UPDATE movimientos_caja SET estado = 'REPUESTO'
     WHERE caja_chica_id = p_id_caja AND estado = 'PENDIENTE' AND activo = 1;

    COMMIT;
    SELECT v_gasto_id AS gasto_id, v_total_pendiente AS total_repuesto;
END$$

