DELIMITER $$
CREATE TRIGGER `tr_inmutabilidad_presupuesto_upd` BEFORE UPDATE ON `presupuesto` FOR EACH ROW BEGIN
    DECLARE v_pagos INT DEFAULT 0;
    
    
    SELECT COUNT(*) INTO v_pagos
    FROM detalles_presupuesto dp
    JOIN presupuesto_mensualidad pm ON dp.id_detalle_presupuesto = pm.detalle_presupuesto_id
    JOIN pagos_mensualidad p_m ON pm.mensualidad_id = p_m.mensualidad_id
    JOIN pagos p ON p_m.pago_id = p.id_pago
    WHERE dp.presupuesto_id = OLD.id_presupuesto
      AND p.activo = 1 
      AND p.estado IN ('PROCESADO', 'PENDIENTE');

    
    IF v_pagos > 0 AND (OLD.cuota_reserva != NEW.cuota_reserva OR OLD.tasa_dolar != NEW.tasa_dolar OR OLD.activo != NEW.activo) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Presupuesto bloqueado. Existen transacciones financieras dependientes de esta estructura base.';
    END IF;
END
$$
DELIMITER ;

