--
-- Estructura para la vista `vw_estado_cuentas_mensualidad`
--
DROP TABLE IF EXISTS `vw_estado_cuentas_mensualidad`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_estado_cuentas_mensualidad`  AS SELECT `m`.`id_mensualidad` AS `id_mensualidad`, `m`.`apartamento_id` AS `apartamento_id`, `a`.`nro_apartamento` AS `nro_apartamento`, `p`.`mes` AS `mes`, `p`.`anio` AS `anio`, `m`.`monto`- `m`.`descuento` AS `monto_cuota`, round((`m`.`monto` - `m`.`descuento`) / `p`.`tasa_dolar`,2) AS `monto_cuota_usd`, `p`.`tasa_dolar` AS `tasa_historica`, coalesce(`abonos`.`total_abonado`,0) AS `total_abonado`, `m`.`monto`- `m`.`descuento` - coalesce(`abonos`.`total_abonado`,0) AS `deuda_pendiente`, str_to_date(concat(`p`.`anio`,'-',lpad(`p`.`mes`,2,'0'),'-01'),'%Y-%m-%d') + interval `m`.`limite_mensualidad` day AS `fecha_vencimiento`, least(curdate(),coalesce((select min(`dp`.`fecha`) from ((`pagos_mensualidad` `pm` join `pagos` `pg` on(`pm`.`pago_id` = `pg`.`id_pago`)) join `detalles_pagos` `dp` on(`pg`.`id_pago` = `dp`.`pago_id`)) where `pm`.`mensualidad_id` = `m`.`id_mensualidad` and `pg`.`activo` = 1 and ucase(`pg`.`estado`) = 'PENDIENTE'),curdate())) AS `fecha_corte_mora`, CASE WHEN `m`.`monto` - `m`.`descuento` - coalesce(`abonos`.`total_abonado`,0) <= 0 THEN 0 WHEN least(curdate(),coalesce((select min(`dp`.`fecha`) from ((`pagos_mensualidad` `pm` join `pagos` `pg` on(`pm`.`pago_id` = `pg`.`id_pago`)) join `detalles_pagos` `dp` on(`pg`.`id_pago` = `dp`.`pago_id`)) where `pm`.`mensualidad_id` = `m`.`id_mensualidad` AND `pg`.`activo` = 1 AND ucase(`pg`.`estado`) = 'PENDIENTE'),curdate())) <= str_to_date(concat(`p`.`anio`,'-',lpad(`p`.`mes`,2,'0'),'-01'),'%Y-%m-%d') + interval `m`.`limite_mensualidad` day THEN 0 ELSE round((`m`.`monto` - `m`.`descuento` - coalesce(`abonos`.`total_abonado`,0)) * `m`.`porcentaje_interes` / 100,2) END AS `monto_mora`, `m`.`monto`- `m`.`descuento` - coalesce(`abonos`.`total_abonado`,0) + CASE WHEN `m`.`monto` - `m`.`descuento` - coalesce(`abonos`.`total_abonado`,0) <= 0 THEN 0 WHEN least(curdate(),coalesce((select min(`dp`.`fecha`) from ((`pagos_mensualidad` `pm` join `pagos` `pg` on(`pm`.`pago_id` = `pg`.`id_pago`)) join `detalles_pagos` `dp` on(`pg`.`id_pago` = `dp`.`pago_id`)) where `pm`.`mensualidad_id` = `m`.`id_mensualidad` AND `pg`.`activo` = 1 AND ucase(`pg`.`estado`) = 'PENDIENTE'),curdate())) <= str_to_date(concat(`p`.`anio`,'-',lpad(`p`.`mes`,2,'0'),'-01'),'%Y-%m-%d') + interval `m`.`limite_mensualidad` day THEN 0 ELSE round((`m`.`monto` - `m`.`descuento` - coalesce(`abonos`.`total_abonado`,0)) * `m`.`porcentaje_interes` / 100,2) END AS `deuda_con_mora`, round(greatest(0,`m`.`monto` - `m`.`descuento` - coalesce(`abonos`.`total_abonado`,0) + case when `m`.`monto` - `m`.`descuento` - coalesce(`abonos`.`total_abonado`,0) <= 0 then 0 when least(curdate(),coalesce((select min(`dp`.`fecha`) from ((`pagos_mensualidad` `pm` join `pagos` `pg` on(`pm`.`pago_id` = `pg`.`id_pago`)) join `detalles_pagos` `dp` on(`pg`.`id_pago` = `dp`.`pago_id`)) where `pm`.`mensualidad_id` = `m`.`id_mensualidad` and `pg`.`activo` = 1 and ucase(`pg`.`estado`) = 'PENDIENTE'),curdate())) <= str_to_date(concat(`p`.`anio`,'-',lpad(`p`.`mes`,2,'0'),'-01'),'%Y-%m-%d') + interval `m`.`limite_mensualidad` day then 0 else round((`m`.`monto` - `m`.`descuento` - coalesce(`abonos`.`total_abonado`,0)) * `m`.`porcentaje_interes` / 100,2) end) / `p`.`tasa_dolar`,2) AS `deuda_usd`, CASE ENDselect min(`dp`.`fecha`) END FROM ((`pagos_mensualidad` `pm` join `pagos` `pg` on(`pm`.`pago_id` = `pg`.`id_pago`)) join `detalles_pagos` `dp` on(`pg`.`id_pago` = `dp`.`pago_id`)) WHERE `pm`.`mensualidad_id` = `m`.`id_mensualidad` AND `pg`.`activo` = 1 AND ucase(`pg`.`estado`) = 'PENDIENTE'from (((`mensualidad` `m` join `apartamentos` `a` on(`m`.`apartamento_id` = `a`.`id_apartamento`)) join `periodos_mensualidad` `p` on(`m`.`periodo_id` = `p`.`id_periodo`)) left join (select `pm`.`mensualidad_id` AS `mensualidad_id`,sum(`pm`.`monto_abonado`) AS `total_abonado` from (`pagos_mensualidad` `pm` join `pagos` `pg` on(`pm`.`pago_id` = `pg`.`id_pago`)) where `pg`.`activo` = 1 and ucase(`pg`.`estado`) = 'PROCESADO' group by `pm`.`mensualidad_id`) `abonos` on(`m`.`id_mensualidad` = `abonos`.`mensualidad_id`)) where `m`.`activo` = 1 and `a`.`activo` = 1 and `p`.`activo` = 1  ;

